import json,os
L=r'D:\股票数据\市场数据\_学习'
# ---- 先做一次可复算的校验：末5荐票日 套票因子计数 ----
rows=[json.loads(l) for l in open(os.path.join(L,'_涨停质量反思.jsonl'),encoding='utf-8') if l.strip()]
last5=rows[-5:]
print('末5荐票日',[r['荐票日'] for r in last5])
cnt={}
for r in last5:
    for k in r.get('套票因子',{}): cnt[k]=cnt.get(k,0)+1
print('套票因子天数计数',cnt,'增益pp',[r['选股增益pp'] for r in last5])
json.dump(cnt,open(os.path.join(L,'_tmp_ext_cnt_20261014.json'),'w',encoding='utf-8'),ensure_ascii=False)

